#include <bits/stdc++.h>
using namespace std;

int main() {
    int n, m;
    if (scanf("%d %d", &n, &m) != 2) return 0;

    vector<int> t(n);
    for (int i = 0; i < n; i++) scanf("%d", &t[i]);
    vector<int> f(m);
    for (int j = 0; j < m; j++) scanf("%d", &f[j]);

    // Sort cars by base time, descending: largest jobs should get smallest multipliers
    sort(t.begin(), t.end(), greater<int>());

    // Min-heap over machines keyed by the next available multiplier F_j * k_j.
    // The multiset of available multipliers is {F_j * k : k >= 0} per machine;
    // greedily taking the globally smallest multiplier for the next largest car
    // yields the N smallest elements of that multiset (with valid per-machine
    // prefixes), which is optimal by rearrangement/exchange arguments.
    priority_queue<pair<long long, int>,
                   vector<pair<long long, int>>,
                   greater<pair<long long, int>>> pq;
    for (int j = 0; j < m; j++) pq.push(make_pair(0LL, j));

    vector<long long> cnt(m, 0);
    long long ans = 0;
    for (int i = 0; i < n; i++) {
        pair<long long, int> top = pq.top();
        pq.pop();
        long long c = top.first;
        int j = top.second;
        ans += (long long)t[i] * c;
        cnt[j]++;
        pq.push(make_pair((long long)f[j] * cnt[j], j));
    }

    printf("%lld\n", ans);
    return 0;
}
